import * as E from './engine.js';
function col(key,label,opts={}){return {key,label,value:r=>r[key],...opts};}
const price=(key,label)=>col(key,label,{numeric:true,roundCopy:true,exportLabel:label+'(만원/평)',width:108});
const money=(key,label)=>col(key,label,{numeric:true,exportLabel:label+'(만 원)',width:108});
const base=[col('name','단지명',{width:140}),col('year','건축년도',{sort:r=>Number(r.year.split(',')[0])||Infinity}),col('dong','행정동',{exportLabel:'행정동(원본 동)'}),col('region','시군구'),col('address','주소',{width:80})];
export const COLUMNS={apartments:[...base,col('pyeongText','면적(평형)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:110}),col('areaText','전용면적(㎡)',{sort:r=>r.areaMin,tie:r=>r.areaMax,width:120}),col('typeText','타입',{width:76,sort:r=>r.type}),price('minimum','최소평당가'),price('maximum','최대평당가'),price('average','평균평당가'),money('priceMinimum','최소 거래금액'),money('priceMaximum','최대 거래금액'),money('priceAverage','평균 거래금액'),col('count','거래 건수',{numeric:true})],districts:[base[2],base[3],base[0],base[1],price('average','평균평당가'),col('count','거래 건수',{numeric:true})],excluded:[col('rowNumber','원본 행',{numeric:true}),base[0],base[4],col('area','전용면적(㎡)',{value:r=>Number.isFinite(r.area)?E.areaText(r.area):'',sort:r=>r.area}),col('broker','중개사 소재지',{width:230}),col('reason','제외 사유',{width:160})],cases:[col('date','계약일',{value:r=>r.date||'날짜 미확인',sort:r=>r.date||'9999'}),base[0],col('area','전용면적(㎡)',{value:r=>E.areaText(r.area),sort:r=>r.area}),col('type','타입',{value:r=>r.type+'타입',sort:r=>r.type}),col('floor','층',{sort:r=>E.number(r.floor)}),money('price','거래금액'),price('unitPrice','평당가')]};
